"""Build and execute a Colab-compatible notebook using ordinary Python cells."""
from pathlib import Path
import json,io,contextlib,base64,os
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]
source=(ROOT/'project/train_model.py').read_text().replace('ROOT=Path(__file__).resolve().parents[1]',"ROOT=Path.cwd()\n(ROOT/'project').mkdir(exist_ok=True)").replace("if __name__=='__main__':main()",'')
def md(s):return {'cell_type':'markdown','metadata':{},'source':s}
def code(s):return {'cell_type':'code','metadata':{},'source':s,'execution_count':None,'outputs':[]}
cells=[
 md('# SalesCast-AI — Sales and Demand Forecasting\n\n**Kunene · Executed project notebook**\n\nTrain calendar Ridge regressions, compare weekly baselines, preserve time order, and evaluate an independent final test. All demonstration sales, prices, and stock assumptions are synthetic. The live browser application can fit the same models to your own valid sales CSV.'),
 md('## 1. Imports, fixed seed, and model definitions\n\nThis notebook requires NumPy, scikit-learn, and Matplotlib. Colab normally includes them; the exact project versions are listed in requirements.txt. Calendar regression uses L2 penalty alpha = 3. The intercept is not regularised. The code below includes the complete reproducible data generator and modelling pipeline.'),
 code(source),
 md('## 2. Generate sales, validate chronologically, and train\n\nSix products × 730 days = 4,380 observations. At each product, use two expanding-window validation forecasts of 28 days, select the method using only those validation errors, and leave the final 28-day window for independent evaluation. Refit on all observed history for future forecasts.'),
 code("report=main()\nprint('Weekly baseline test WAPE:', sum(p['weekly_test']['absoluteError'] for p in report['products'])/sum(p['weekly_test']['totalActual'] for p in report['products']))"),
 md('## 3. Compare the measured product results\n\nWAPE is the sum of absolute errors divided by actual units. It is an error rate, not an accuracy score. The model choice below was determined before the final test was examined.'),
 code("print(f\"{'Product':23s} {'Method':8s} {'Ridge WAPE':>12s} {'Weekly WAPE':>12s} {'MAE':>9s}\")\nfor p in report['products']:\n    print(f\"{p['product']:23s} {p['selected']:8s} {100*p['ridge_test']['wape']:11.2f}% {100*p['weekly_test']['wape']:11.2f}% {p['test']['mae']:9.3f}\")\nprint('Planning-range test coverage:', sum(p['test_coverage'] for p in report['products'])/len(report['products']))"),
 md('## 4. Inspect the independent test and model comparison\n\nThe first chart overlays predictions for the last 28 days on observed Moringa Capsule sales. Its range uses earlier validation errors. The second chart compares product-level held-out errors.'),
 code("import matplotlib.pyplot as plt\nfrom matplotlib.ticker import PercentFormatter\nwith (ROOT/'dist/data/demo_sales.csv').open() as f:\n    rows=list(csv.DictReader(f))\nselected=report['products'][0]\nrecords=[r for r in rows if r['product']==selected['product']]\ndates=[date.fromisoformat(r['date']) for r in records]\ndays=np.array([(d-date(1970,1,1)).days for d in dates])\nunits=np.array([float(r['units']) for r in records])\ncut=len(units)-28\nfitted=ridge_fit(days[:cut],units[:cut],int(days[0]),True)\npred=ridge_predict(fitted,days[cut:],int(days[0]),True) if selected['selected']=='ridge' else weekly(units[:cut],28)\nplt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.labelcolor':'#425a80','text.color':'#23395c'})\nfig,axes=plt.subplots(1,2,figsize=(13,4.3),gridspec_kw={'width_ratios':[1.3,1]})\naxes[0].plot(dates[-90:],units[-90:],color='#5f84e7',lw=1.5,label='Observed sales')\naxes[0].plot(dates[cut:],pred,color='#d79958',lw=2,label='Held-out prediction')\naxes[0].fill_between(dates[cut:],np.maximum(0,pred-selected['range_radius']),pred+selected['range_radius'],color='#edcba2',alpha=.38,label='Planning range')\naxes[0].axvline(dates[cut],ls='--',color='#b8a58b',lw=1)\naxes[0].set(title='Moringa Capsules: final 28-day test',ylabel='Units per day')\naxes[0].tick_params(axis='x',labelrotation=25,labelsize=8)\naxes[0].legend(fontsize=8,loc='upper left')\nx=np.arange(len(report['products']))\naxes[1].bar(x-.17,[p['ridge_test']['wape'] for p in report['products']],.34,color='#6f8fe8',label='Calendar Ridge')\naxes[1].bar(x+.17,[p['weekly_test']['wape'] for p in report['products']],.34,color='#e0b285',label='Weekly baseline')\naxes[1].set_xticks(x,[p['product'].replace(' ','\\n',1) for p in report['products']],fontsize=7)\naxes[1].yaxis.set_major_formatter(PercentFormatter(1))\naxes[1].set(title='Independent test WAPE by product',ylabel='WAPE — lower is better')\naxes[1].legend(fontsize=8)\nfor ax in axes:ax.grid(axis='y',alpha=.18);ax.set_axisbelow(True)\nfig.tight_layout()\nfig.savefig(ROOT/'project/model_evaluation.png',dpi=180,bbox_inches='tight')\nplt.show()"),
 md('## 5. Forecast the portfolio\n\nThe shaded bounds are sums of the product planning ranges. They do not constitute an 80% portfolio confidence interval. No future actuals are used.'),
 code("fixtures=json.loads((ROOT/'project/python_fixtures.json').read_text())\nhistorical=np.sum([np.array([float(r['units']) for r in rows if r['product']==p['product']]) for p in CATALOG],axis=0)\nforecast=np.sum([np.array(p['forecast_first_30']) for p in fixtures],axis=0)\nlower=np.sum([np.maximum(0,np.array(p['forecast_first_30'])-p['radius']) for p in fixtures],axis=0)\nupper=np.sum([np.array(p['forecast_first_30'])+p['radius'] for p in fixtures],axis=0)\nfuture_dates=[dates[-1]+timedelta(days=i+1) for i in range(30)]\nfig,ax=plt.subplots(figsize=(11,4))\nax.plot(dates[-90:],historical[-90:],color='#6b8de7',lw=1.6,label='Observed portfolio sales')\nax.plot([dates[-1],*future_dates],[historical[-1],*forecast],color='#d79958',lw=2,label='30-day point forecast')\nax.fill_between(future_dates,lower,upper,color='#edcba2',alpha=.4,label='Summed planning envelope')\nax.axvline(dates[-1],color='#b8a58b',ls='--',lw=1)\nax.set(title='SalesCast-AI: portfolio forecast',ylabel='Units per day',xlabel='Date')\nax.grid(axis='y',alpha=.18);ax.legend(fontsize=8);fig.tight_layout()\nfig.savefig(ROOT/'project/portfolio_forecast.png',dpi=180,bbox_inches='tight')\nprint('Forecast units, next 30 days:',round(float(forecast.sum()),3))\nprint('All records shown here are synthetic.')\nplt.show()"),
 md('## 6. Reproduce the browser result\n\n`project/python_fixtures.json` contains the learned coefficients, selected model, planning-range radius, first 30 forecasts, and test predictions for each product. `npm test` compares these against the independent browser implementation and verifies chronology, CSV validation, and stock calculations.\n\nRun the app with `python -m http.server 8000 --directory dist`, then open http://localhost:8000. To forecast your own sales without editing this demonstration pipeline, use the app’s validated CSV import.\n\nReference: [scikit-learn Ridge](https://scikit-learn.org/stable/modules/generated/sklearn.linear_model.Ridge.html).')
]
notebook={'cells':cells,'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.12'},'colab':{'provenance':[]}},'nbformat':4,'nbformat_minor':5}
os.chdir(ROOT);namespace={'__name__':'__main__'};count=0
for i,cell in enumerate(cells):
    cell['id']=f'salescast-{i:02d}'
    if cell['cell_type']!='code':continue
    count+=1;stream=io.StringIO()
    with contextlib.redirect_stdout(stream):exec(compile(cell['source'],f'<notebook cell {count}>','exec'),namespace)
    cell['execution_count']=count
    if stream.getvalue():cell['outputs'].append({'output_type':'stream','name':'stdout','text':stream.getvalue()})
    for number in plt.get_fignums():
        figure=plt.figure(number);buffer=io.BytesIO();figure.savefig(buffer,format='png',dpi=135,bbox_inches='tight')
        cell['outputs'].append({'output_type':'display_data','data':{'image/png':base64.b64encode(buffer.getvalue()).decode(),'text/plain':['<Executed Matplotlib figure>']},'metadata':{}})
    plt.close('all')
(ROOT/'dist/SalesCast_Training_Kunene.ipynb').write_text(json.dumps(notebook,indent=1))
print(json.dumps({'executed_code_cells':count,'failed_cells':0,'notebook':'dist/SalesCast_Training_Kunene.ipynb'}))
